<template>
  <section class="agent-workspace" aria-label="协作式设计工作区">
    <aside class="session-rail" aria-label="设计对话列表">
      <button type="button" class="new-session" :disabled="creating" @click="create"><span aria-hidden="true">＋</span> 新建对话</button>
      <p v-if="sessionsLoading" class="rail-note">正在读取对话…</p>
      <nav v-else class="session-list" aria-label="对话">
        <button v-if="isNewDraft" type="button" class="session-item active" @click="create"><strong>新建对话</strong><small>尚未发送</small></button>
        <button v-for="item in sessions" :key="item.session_id" type="button" :class="['session-item', { active: item.session_id === currentSessionId }]" @click="select(item.session_id)">
          <strong>{{ item.title }}</strong><small>{{ sessionLabel(item) }} · {{ formatShortDate(item.updated_at) }}</small>
          <i v-if="item.has_pending_action" aria-label="有待确认事项">●</i>
        </button>
        <p v-if="!isNewDraft && !sessions.length" class="session-list-empty">还没有对话<br><small>从一个新的文创构思开始</small></p>
      </nav>
    </aside>

    <main class="conversation-stage">
      <header class="conversation-stage__header">
        <div><p class="section-index">自然对话</p><h1>{{ currentTitle }}</h1></div>
        <button v-if="currentSession" type="button" class="archive-link" @click="newTaskOpen = true">开始新的设计</button>
      </header>
      <p v-if="currentError" class="agent-error" role="alert">{{ currentError }}</p>
      <section ref="messageList" class="message-list" aria-live="polite" aria-label="消息历史">
        <div v-if="sessionLoadingById[currentSessionId] && !currentSession" class="empty-state">正在打开这个设计对话…</div>
        <template v-else>
          <article v-for="message in currentMessages" :key="message.id" :class="['message', message.role, { pending: message.pending, failed: message.failed }]">
            <p class="message__speaker">{{ message.role === 'user' ? '你' : '设计助手' }}</p>
            <template v-if="isSafeReply(message.structured_output)">
              <p class="conversation-reply">{{ message.structured_output.message }}</p>
              <div v-if="message.structured_output.suggestions?.length" class="conversation-suggestions"><button v-for="suggestion in message.structured_output.suggestions" :key="suggestion.label" type="button" class="quiet-button" @click="useSuggestion(suggestion)">{{ suggestion.label }}</button></div>
              <section v-if="validArtifact(message.structured_output)" class="attachment-card"><p class="card-eyebrow">{{ artifactTitle(message.structured_output.artifact_proposal) }}</p><strong>{{ message.structured_output.artifact_proposal.summary }}</strong><dl><template v-for="row in artifactRows(message.structured_output.artifact_proposal)" :key="row[0]"><dt>{{ row[0] }}</dt><dd>{{ row[1] }}</dd></template></dl><small>这是一项建议；保存后才会写入设计档案。</small></section>
            </template>
            <p v-else-if="message.role === 'assistant' && message.message_type === 'runtime_result'">本轮协作回复暂时不可展示，请继续描述你的想法或稍后重试。</p>
            <p v-else>{{ message.text }}</p>
            <small v-if="message.pending" class="message-status">正在发送并等待设计助手回应…</small>
            <div v-if="message.failed" class="message-retry"><small>本轮未完成。原问题已保留。</small><button type="button" class="quiet-button" @click="regenerate(message)">重新发送</button></div>
            <time>{{ formatTime(message.created_at) }}</time>
          </article>
          <section v-if="latestRuntimeAction" class="action-confirmation-card"><p class="card-eyebrow">需要你的确认</p><h3>{{ latestRuntimeAction.label }}</h3><p>{{ latestRuntimeAction.reason }}</p><dl><template v-if="latestRuntimeAction.display?.source_type"><dt>依据</dt><dd>{{ latestRuntimeAction.display.source_type === 'conversation_snapshot' ? '当前对话快照' : '已保存的设计内容' }}</dd></template><template v-if="latestRuntimeAction.display?.confirmed_constraints?.length"><dt>已确认</dt><dd>{{ latestRuntimeAction.display.confirmed_constraints.join('、') }}</dd></template><template v-if="latestRuntimeAction.display?.tentative_assumptions?.length"><dt>暂定</dt><dd>{{ latestRuntimeAction.display.tentative_assumptions.join('、') }}</dd></template><template v-if="latestRuntimeAction.display?.presentation_mode"><dt>展示方式</dt><dd>{{ latestRuntimeAction.display.presentation_mode }}</dd></template></dl><label v-if="isImageAction(latestRuntimeAction.actionType)" class="cost-check"><input v-model="latestRuntimeAction.costConfirmed" type="checkbox"> 我同意使用以上暂定假设并确认执行图片生成</label><div><button type="button" class="secondary-button" :disabled="Boolean(actionBusyByRun[latestRuntimeAction.runId])" @click="continueAdjusting(latestRuntimeAction)">继续调整</button><button type="button" class="primary-button" :disabled="Boolean(actionBusyByRun[latestRuntimeAction.runId]) || (isImageAction(latestRuntimeAction.actionType) && !latestRuntimeAction.costConfirmed)" @click="beginAction(latestRuntimeAction)">{{ actionBusyByRun[latestRuntimeAction.runId] ? '正在提交…' : latestRuntimeAction.confirmLabel }}</button></div></section>
          <section v-if="currentSession && latestRequestedAction" class="action-resume-card"><p class="card-eyebrow">待确认</p><strong>{{ actionLabel(latestRequestedAction.action_type) }}</strong><p>{{ latestRequestedAction.safe_summary }}</p><button type="button" class="primary-button" :disabled="actionBusyByRun[latestRequestedAction.id]" @click="resumeRequestedAction(latestRequestedAction)">查看并确认</button></section>
          <section v-if="!currentMessages.length" class="empty-state agent-empty-state"><p class="section-index">开始一个文创设计</p><h2>把想法说出来</h2><p>你可以从产品构思、文化研究、方案比较或设计批评开始。</p><div><button v-for="example in emptyExamples" :key="example" type="button" class="quiet-button" @click="useExample(example)">{{ example }}</button></div></section>
          <div v-if="pendingBySessionId[draftKey]" class="agent-thinking"><span></span>正在整理这轮对话…</div>
        </template>
      </section>
      <form class="agent-composer" @submit.prevent="send">
        <label class="sr-only" for="agent-message">描述你的文创产品需求</label>
        <textarea id="agent-message" v-model="draftsBySessionId[draftKey]" rows="3" :disabled="Boolean(pendingBySessionId[draftKey])" placeholder="继续补充产品、场景、风格，或讨论刚才的方案…"></textarea>
        <div><small>{{ activeTask ? `当前设计：${activeTask.title}` : '普通对话不需要先建立设计项目' }}</small><button type="submit" class="primary-button" :disabled="!currentDraft.trim() || Boolean(pendingBySessionId[draftKey])">发送</button></div>
      </form>
    </main>

    <aside :class="['design-archive', { 'design-archive--open': archiveOpen }]" aria-label="设计档案">
      <header><div><p class="section-index">设计档案</p><h2>当前设计</h2></div><button type="button" class="archive-close" aria-label="关闭设计档案" @click="archiveOpen = false">×</button></header>
      <template v-if="currentSession">
        <label class="task-select"><span>当前设计</span><select :value="activeTask?.id || ''" @change="selectActiveTask($event.target.value)"><option value="">未建立设计项目</option><option v-for="task in selectableTasks" :key="task.id" :value="task.id">{{ task.title }}{{ task.status === 'closed' ? '（只读）' : '' }}</option></select></label>
        <button type="button" class="new-task-link" @click="openNewTask">＋ 开始新的设计</button>
        <section class="archive-group"><h3>已保存内容</h3><p v-if="!activeTask" class="muted">建立设计项目后，这里会记录你明确保存的版本。</p><ul v-else-if="nonImageArtifacts.length"><li v-for="artifact in nonImageArtifacts" :key="artifact.id"><button type="button" @click="selectedArtifact = artifact"><strong>{{ artifactLabel(artifact.artifact_type) }} V{{ artifact.version_number }}</strong><small>{{ artifact.origin === 'legacy_projection' ? '历史记录 · 只读' : artifact.status === 'superseded' ? '历史版本' : '已保存' }}</small></button></li></ul><p v-else class="muted">还没有正式保存的内容。</p></section>
        <section class="archive-group"><h3>图片版本</h3><p v-if="!imageArtifacts.length" class="muted">图片结果会在明确确认后保留在这里。</p><ul v-else class="image-version-list"><li v-for="image in imageArtifacts" :key="image.id"><button type="button" @click="selectedArtifact = image"><span>试稿 V{{ image.version_number }}</span><small>{{ image.parent_artifact_id ? '基于上一版修改' : imageOriginLabel(image) }}</small></button></li></ul></section>
        <section v-if="activeActions.length" class="archive-group"><h3>待确认与恢复</h3><ul class="action-index"><li v-for="action in activeActions" :key="action.id"><button type="button" @click="focusAction(action)"><strong>{{ actionLabel(action.action_type) }}</strong><small>{{ actionStatusLabel(action.status) }}</small></button></li></ul></section>
      </template>
      <p v-else class="muted">选择一个对话后查看其设计档案。</p>
    </aside>
    <button type="button" class="archive-toggle" aria-controls="design-archive" @click="archiveOpen = !archiveOpen">设计档案</button>

    <div v-if="newTaskOpen" class="dialog-backdrop" @click.self="newTaskOpen = false"><form class="task-dialog" @submit.prevent="createNewTask"><p class="section-index">开始新的设计</p><h2>{{ pendingProposal ? '把当前讨论建立为设计项目' : '新建设计项目' }}</h2><p>设计项目只记录你明确保存或生成的版本；普通聊天仍可独立继续。</p><label>设计名称<input v-model="newTaskTitle" required maxlength="255" placeholder="例如：景德镇山水杯垫"></label><label>初始目标（可选）<textarea v-model="newTaskGoal" rows="3" maxlength="2000" placeholder="写下一句想先解决的设计目标"></textarea></label><div><button type="button" class="secondary-button" @click="cancelTask">暂不</button><button type="submit" class="primary-button" :disabled="taskCreating">{{ taskCreating ? '正在建立' : '建立并继续' }}</button></div></form></div>
    <div v-if="selectedArtifact" class="dialog-backdrop" @click.self="selectedArtifact = null"><section class="artifact-dialog"><button type="button" class="dialog-dismiss" aria-label="关闭" @click="selectedArtifact = null">×</button><p class="section-index">{{ artifactLabel(selectedArtifact.artifact_type) }} · V{{ selectedArtifact.version_number }}</p><h2>{{ selectedArtifact.origin === 'legacy_projection' ? '历史记录（只读）' : '已保存设计内容' }}</h2><img v-if="artifactImageUrl(selectedArtifact) && !imageLoadErrors[selectedArtifact.id]" :src="artifactImageUrl(selectedArtifact)" alt="已生成的设计试稿" @error="imageLoadErrors[selectedArtifact.id] = true"><p v-else-if="selectedArtifact.artifact_type === 'generated_image'" class="image-fallback">图片暂时无法加载。版本记录仍已保留。</p><dl v-else><template v-for="(value, key) in safeEntries(selectedArtifact.safe_content)" :key="key"><dt>{{ contentLabel(key) }}</dt><dd>{{ value }}</dd></template></dl></section></div>
  </section>
</template>

<script>
import { createClientId } from '../utils/clientId'
import { approveAction, createSession, createTask, executeAction, getRuntimeActionProposal, getSession, listActions, listArtifacts, listSessions, listTasks, rejectAction, requestAction, runAssistantTurn, selectTask } from '../services/agentDialogueApi'

const IMAGE_ACTIONS = new Set(['generate_image_from_conversation', 'generate_image_from_artifact', 'regenerate_image'])
const DOMAIN_ACTIONS = new Set(['save_brief', 'save_design_text', 'apply_revision', 'build_visual_direction', 'generate_image_from_conversation', 'generate_image_from_artifact', 'regenerate_image', 'archive_task'])

export default {
  name: 'AgentDesignPanel',
  data: () => ({
    sessions: [], sessionsById: {}, messagesBySessionId: {}, draftsBySessionId: {}, pendingBySessionId: {}, optimisticBySessionId: {}, sessionLoadingById: {}, errorsBySessionId: {}, runtimeBySessionId: {}, actionRunByMessageId: {}, proposalDisplayByRun: {}, runtimeActionBySessionId: {}, actionBusyByRun: {},
    tasksBySessionId: {}, activeTaskBySessionId: {}, artifactsByTaskId: {}, actionsByTaskId: {}, currentSessionId: '', isNewDraft: false, sessionsLoading: false, creating: false, archiveOpen: false, newTaskOpen: false, newTaskTitle: '', newTaskGoal: '', taskCreating: false, pendingProposal: null, selectedArtifact: null, imageLoadErrors: {},
    emptyExamples: ['设计一款景德镇风格的陶瓷杯垫', '评价一下我的文字稿', '根据当前想法先出一版试稿'],
  }),
  computed: {
    draftKey() { return this.currentSessionId || '__new_draft__' },
    currentSession() { return this.sessionsById[this.currentSessionId] || null },
    currentTitle() { return this.sessions.find((item) => item.session_id === this.currentSessionId)?.title || (this.isNewDraft ? '新对话' : '协作式设计') },
    currentDraft() { return this.draftsBySessionId[this.draftKey] || '' },
    currentError() { return this.errorsBySessionId[this.draftKey] || '' },
    currentMessages() { const key = this.draftKey; const server = this.messagesBySessionId[key] || []; const local = Object.values(this.optimisticBySessionId[key] || {}).filter((item) => !server.some((message) => message.client_turn_id && message.client_turn_id === item.client_turn_id)); return [...server, ...local] },
    activeTask() { return this.activeTaskBySessionId[this.currentSessionId] || null },
    selectableTasks() { return this.tasksBySessionId[this.currentSessionId] || [] },
    artifacts() { return this.activeTask ? this.artifactsByTaskId[this.activeTask.id] || [] : [] },
    nonImageArtifacts() { return this.artifacts.filter((item) => item.artifact_type !== 'generated_image').sort((a, b) => b.version_number - a.version_number) },
    imageArtifacts() { return this.artifacts.filter((item) => item.artifact_type === 'generated_image').sort((a, b) => a.version_number - b.version_number) },
    activeActions() { return this.activeTask ? (this.actionsByTaskId[this.activeTask.id] || []).filter((item) => ['requested', 'approved', 'running', 'failed'].includes(String(item.status))) : [] },
    latestRequestedAction() { return this.activeActions.find((item) => String(item.status) === 'requested') || null },
    latestRuntimeAction() { return this.runtimeActionBySessionId[this.currentSessionId] || null },
  },
  async mounted() { window.addEventListener('popstate', this.restoreFromUrl); await this.loadSessions(); await this.restoreFromUrl() },
  beforeUnmount() { window.removeEventListener('popstate', this.restoreFromUrl) },
  methods: {
    async loadSessions() { this.sessionsLoading = true; try { this.sessions = await listSessions() } catch (error) { this.errorsBySessionId[this.draftKey] = this.errorText(error) } finally { this.sessionsLoading = false } },
    setUrl(id) { const url = new URL(window.location.href); url.searchParams.set('creation_mode', 'agent'); if (id) url.searchParams.set('agent_session_id', id); else url.searchParams.delete('agent_session_id'); window.history.pushState({}, '', url) },
    async restoreFromUrl() { const id = new URLSearchParams(window.location.search).get('agent_session_id') || localStorage.getItem('agent_workspace_session'); if (id) await this.select(id, false); else if (!this.sessions.length) this.create() },
    create() { if (this.isNewDraft) return; this.isNewDraft = true; this.currentSessionId = ''; this.draftsBySessionId.__new_draft__ ||= ''; this.setUrl(null) },
    startNew() { this.create() },
    async select(id, changeUrl = true) { if (!id) return; if (changeUrl) this.setUrl(id); this.isNewDraft = false; this.currentSessionId = id; localStorage.setItem('agent_workspace_session', id); await this.loadSession(id) },
    async loadSession(id) { this.sessionLoadingById[id] = true; try { const session = await getSession(id); this.sessionsById[id] = session; this.messagesBySessionId[id] = session.messages || []; this.reconcileOptimistic(id); await this.loadTaskData(id); if (!this.sessions.some((item) => item.session_id === id)) await this.loadSessions() } catch (error) { this.errorsBySessionId[id] = this.errorText(error) } finally { this.sessionLoadingById[id] = false } },
    async loadTaskData(sessionId) { try { const tasks = await listTasks(sessionId); this.tasksBySessionId[sessionId] = tasks; const active = tasks.find((task) => task.is_active) || this.activeTaskBySessionId[sessionId] || null; this.activeTaskBySessionId[sessionId] = active; if (active) await this.loadDesignArchive(sessionId, active.id) } catch (error) { this.errorsBySessionId[sessionId] = this.errorText(error) } },
    async loadDesignArchive(sessionId, taskId) { const [artifacts, actions] = await Promise.all([listArtifacts(sessionId, taskId, { includeLegacy: true }), listActions(sessionId, taskId)]); this.artifactsByTaskId[taskId] = artifacts; this.actionsByTaskId[taskId] = actions },
    addOptimistic(key, pending) { this.optimisticBySessionId[key] = { ...(this.optimisticBySessionId[key] || {}), [pending.clientTurnId]: { id: `local-${pending.clientTurnId}`, role: 'user', text: pending.text, client_turn_id: pending.clientTurnId, created_at: new Date().toISOString(), pending: true, failed: false } } },
    moveOptimistic(from, to) { if (from === to) return; this.optimisticBySessionId[to] = { ...(this.optimisticBySessionId[to] || {}), ...(this.optimisticBySessionId[from] || {}) }; delete this.optimisticBySessionId[from] },
    reconcileOptimistic(id) { const pending = { ...(this.optimisticBySessionId[id] || {}) }; for (const message of this.messagesBySessionId[id] || []) if (message.client_turn_id) delete pending[message.client_turn_id]; this.optimisticBySessionId[id] = pending },
    async send({ forceNew = false } = {}) { let id = this.currentSessionId; const key = this.draftKey; const text = this.currentDraft.trim(); const existing = this.pendingBySessionId[key]; if (!text || this.creating || (existing && !forceNew)) return; const pending = { clientTurnId: existing?.clientTurnId || createClientId(), text }; this.pendingBySessionId[key] = pending; this.addOptimistic(key, pending); this.errorsBySessionId[key] = ''; try { if (!id) { this.creating = true; const session = await createSession(); id = session.session_id; this.currentSessionId = id; this.isNewDraft = false; this.sessionsById[id] = session; this.messagesBySessionId[id] = session.messages || []; this.draftsBySessionId[id] = text; this.moveOptimistic(key, id); delete this.pendingBySessionId[key]; this.pendingBySessionId[id] = pending; this.setUrl(id); localStorage.setItem('agent_workspace_session', id) } const response = await runAssistantTurn(id, text, pending.clientTurnId, this.activeTaskBySessionId[id]?.id || null); this.runtimeBySessionId[id] = response.data?.display || {}; this.draftsBySessionId[id] = ''; await this.loadSession(id); const assistant = [...(this.messagesBySessionId[id] || [])].reverse().find((message) => message.role === 'assistant' && message.structured_output?.business_action); if (assistant && response.data?.run?.id) { const runId = response.data.run.id; this.actionRunByMessageId[assistant.id] = runId; const actionType = assistant.structured_output.business_action.action; if (DOMAIN_ACTIONS.has(actionType)) { try { const safe = await getRuntimeActionProposal(id, runId, actionType); this.proposalDisplayByRun[runId] = safe; this.runtimeActionBySessionId[id] = { runId, actionType, label: this.actionLabel(actionType), reason: assistant.structured_output.business_action.reason_summary, display: safe.display, costConfirmed: false, confirmLabel: IMAGE_ACTIONS.has(actionType) ? '确认生成' : '确认保存' } } catch (error) { this.errorsBySessionId[id] = this.actionErrorText(error) } } } await this.loadSessions() } catch (error) { this.draftsBySessionId[id || key] = text; this.errorsBySessionId[id || key] = this.errorText(error); const local = this.optimisticBySessionId[id || key]?.[pending.clientTurnId]; if (local) local.pending = false; if (local) local.failed = true } finally { delete this.pendingBySessionId[id || key]; this.creating = false } },
    useSuggestion(suggestion) { if (!this.currentDraft) this.draftsBySessionId[this.draftKey] = suggestion.draft_text || suggestion.label || '' },
    useExample(example) { if (!this.currentDraft) this.draftsBySessionId[this.draftKey] = example },
    regenerate(message) { this.draftsBySessionId[this.draftKey] = message.text; return this.send({ forceNew: true }) },
    isSafeReply(output) { const text = String(output?.message || '').toLowerCase(); return Boolean(text) && !['previous output was invalid', 'corrected json envelope', 'corrected compact json envelope', 'output repair', 'return only json', 'schema validation', 'validation error'].some((marker) => text.includes(marker)) },
    validArtifact(output) { return output?.artifact_proposal?.valid === true && ['brief', 'design_revision'].includes(output.artifact_proposal.kind) },
    artifactTitle(proposal) { return proposal?.kind === 'design_revision' ? '方案修改建议（尚未应用）' : '设计 Brief（尚未保存）' },
    artifactRows(proposal) { const content = proposal?.content || {}; return [['设计目标', content.design_goal || content.goal], ['产品类型', content.product_type], ['受众', content.target_audience], ['风格', content.style], ['材质／工艺', content.materials || content.material]].filter((row) => row[1]) },
    actionFromMessage(message) { const action = message?.structured_output?.business_action; const runId = this.actionRunByMessageId[message?.id]; const safe = this.proposalDisplayByRun[runId]; if (!action || !runId || !safe || !DOMAIN_ACTIONS.has(action.action) || !['provider', 'provider_repair'].includes(message.structured_output?.output_origin)) return null; return { runId, actionType: action.action, label: this.actionLabel(action.action), reason: action.reason_summary, display: safe.display, costConfirmed: false, confirmLabel: IMAGE_ACTIONS.has(action.action) ? '确认生成' : '确认保存' } },
    async beginAction(proposal) { if (!this.activeTask) { this.pendingProposal = proposal; this.newTaskTitle = this.suggestedTaskTitle(); this.newTaskOpen = true; return } await this.requestApproveExecute(proposal) },
    continueAdjusting(proposal) { this.draftsBySessionId[this.draftKey] = `请继续调整“${proposal.label}”这项建议：`; document.getElementById('agent-message')?.focus() },
    openNewTask() { this.pendingProposal = null; this.newTaskTitle = this.suggestedTaskTitle(); this.newTaskGoal = ''; this.newTaskOpen = true },
    cancelTask() { this.newTaskOpen = false; this.pendingProposal = null },
    suggestedTaskTitle() { return this.currentTitle === '协作式设计' || this.currentTitle === '新对话' ? '新的文创设计' : this.currentTitle },
    async createNewTask() { if (!this.currentSession || !this.newTaskTitle.trim()) return; this.taskCreating = true; try { const task = await createTask(this.currentSessionId, { title: this.newTaskTitle.trim(), initial_goal: this.newTaskGoal.trim() || undefined, client_task_id: createClientId(), select: true, expected_session_version: this.currentSession.version }); this.tasksBySessionId[this.currentSessionId] = [...(this.tasksBySessionId[this.currentSessionId] || []), { ...task, is_active: true }].map((item) => ({ ...item, is_active: item.id === task.id })); this.activeTaskBySessionId[this.currentSessionId] = task; await this.loadDesignArchive(this.currentSessionId, task.id); this.newTaskOpen = false; const proposal = this.pendingProposal; this.pendingProposal = null; if (proposal) await this.requestApproveExecute(proposal) } catch (error) { this.errorsBySessionId[this.currentSessionId] = this.errorText(error) } finally { this.taskCreating = false } },
    async selectActiveTask(taskId) { if (!taskId) { this.activeTaskBySessionId[this.currentSessionId] = null; return } const chosen = this.selectableTasks.find((task) => task.id === taskId); if (!chosen || chosen.status === 'closed') { this.errorsBySessionId[this.currentSessionId] = '已关闭的设计项目只能查看，不能作为当前设计。'; return } try { await selectTask(this.currentSessionId, taskId, this.currentSession?.version); this.activeTaskBySessionId[this.currentSessionId] = chosen; await this.loadDesignArchive(this.currentSessionId, taskId) } catch (error) { this.errorsBySessionId[this.currentSessionId] = this.errorText(error) } },
    async requestApproveExecute(proposal) { const sessionId = this.currentSessionId; const task = this.activeTask; if (!sessionId || !task) return; this.actionBusyByRun[proposal.runId] = true; try { const safeProposal = this.proposalDisplayByRun[proposal.runId] || await getRuntimeActionProposal(sessionId, proposal.runId, proposal.actionType); const request = await requestAction(sessionId, task.id, { action_type: proposal.actionType, idempotency_key: `request-${proposal.runId}`, source_runtime_run_id: proposal.runId, source_proposal_digest: safeProposal.source_proposal_digest, expected_task_version: task.version }); const action = request.data; const approval = { accepted_tentative_assumptions: safeProposal.display?.tentative_assumptions || [], ...(IMAGE_ACTIONS.has(proposal.actionType) ? { cost_confirmation: true, presentation_mode: safeProposal.display?.presentation_mode } : {}) }; await approveAction(action.id, { idempotency_key: `approve-${action.id}`, expected_action_status: 'requested', expected_task_version: task.version, approval_snapshot: approval }); await executeAction(action.id, { idempotency_key: `execute-${action.id}`, expected_action_status: 'approved', expected_task_version: task.version }); await this.loadDesignArchive(sessionId, task.id); await this.loadTaskData(sessionId); await this.loadSession(sessionId) } catch (error) { this.errorsBySessionId[sessionId] = this.actionErrorText(error) } finally { delete this.actionBusyByRun[proposal.runId] } },
    async resumeRequestedAction(action) { if (!window.confirm(`确认${this.actionLabel(action.action_type)}？此操作不会自动重复执行。`)) return; this.actionBusyByRun[action.id] = true; try { const approved = await approveAction(action.id, { idempotency_key: `approve-${action.id}`, expected_action_status: 'requested', expected_task_version: this.activeTask?.version, approval_snapshot: IMAGE_ACTIONS.has(action.action_type) ? { cost_confirmation: true } : {} }); await executeAction(action.id, { idempotency_key: `execute-${action.id}`, expected_action_status: 'approved', expected_task_version: this.activeTask?.version }); await this.loadDesignArchive(this.currentSessionId, this.activeTask.id) } catch (error) { this.errorsBySessionId[this.currentSessionId] = this.actionErrorText(error) } finally { delete this.actionBusyByRun[action.id] } },
    async focusAction(action) { if (action.status === 'requested') await this.resumeRequestedAction(action); else { this.archiveOpen = false; document.getElementById('agent-message')?.focus() } },
    actionLabel(value) { return ({ save_brief: '保存为正式 Brief', save_design_text: '保存文字设计稿', apply_revision: '应用方案修改', build_visual_direction: '保存视觉方向', generate_image_from_conversation: '生成一张试稿', generate_image_from_artifact: '基于设计稿生成图片', regenerate_image: '基于上一版重新生成', archive_task: '归档当前设计' })[value] || '需要确认的设计操作' },
    isImageAction(value) { return IMAGE_ACTIONS.has(value) },
    actionStatusLabel(value) { return ({ requested: '等待确认', approved: '已批准', running: '正在执行', completed: '已完成', rejected: '已拒绝', failed: '执行失败' })[value] || (String(value).includes('unknown') ? '需要人工恢复' : '需要恢复') },
    sessionLabel(item) { return item.has_pending_action ? '有待确认' : item.conversation_status === 'archived' ? '已归档' : '进行中' },
    artifactLabel(value) { return ({ brief: 'Brief', product_design_text: '文字设计稿', visual_direction: '视觉方向', image_prompt: '图片提示', generated_image: '图片试稿' })[value] || '设计内容' },
    imageOriginLabel(item) { return item.safe_content?.source_type === 'conversation_snapshot' ? '依据：当前对话快照' : '已保存图片版本' },
    artifactImageUrl(item) { const content = item?.safe_content || {}; const value = content.image_url || content.resource_url || content.url; return typeof value === 'string' && /^(https?:|mock:|\/)/.test(value) ? value : '' },
    safeEntries(content) { return Object.entries(content || {}).filter(([key, value]) => !['positive_prompt', 'negative_prompt', 'provider_options', 'snapshot_hash'].includes(key) && (typeof value === 'string' || typeof value === 'number')) },
    contentLabel(key) { return ({ title: '名称', product_type: '产品类型', design_goal: '设计目标', concept: '设计概念', summary: '摘要', presentation_mode: '展示方式' })[key] || key.replaceAll('_', ' ') },
    formatShortDate(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '刚刚' : date.toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' }) },
    formatTime(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) },
    actionErrorText(error) { const code = error?.code || error?.response?.data?.code; if (code === 'ACTION_EXECUTION_RECOVERY_REQUIRED') return '本次生成结果需要恢复确认，为避免重复扣费，系统不会自动再次生成。'; if (code === 'ACTION_POLICY_DENIED') return '当前设计条件还不满足这项操作。'; if (String(code || '').includes('IDEMPOTENCY')) return '这项操作已被提交，请先查看当前结果。'; return this.errorText(error) },
    errorText(error) { if (error?.response?.status === 404) return '这个对话或设计项目不存在，或你无权访问。'; if (error?.kind === 'network') return '网络连接暂时不可用；你的输入已保留。'; return error?.message || '协作服务暂时不可用。' },
  },
}
</script>

